    instructionZh: "句中填空：選最自然的詞語。",
    instructionI18n: { "ja": "文中の空欄に入る、最も自然な語を選びましょう。", "en": "Fill in the blank with the most natural word." },
    promptText: "プレゼントを きれいな かみで ___ から、友だちに わたしました。",
    promptContextZh: "把禮物用漂亮的紙___之後，交給了朋友。",
